import {esc,thumbnail,countLabel} from './shared.js';
import {outfitFilters,outfitStyles,outfitTitle,outfitSeasonName,outfitStyleNames} from '../outfit-model.js';
import {displayCode} from '../communication-codes.js';
import {isActiveGarment,isPendingDiscard} from '../garment-status.js';
import {isReconstructed,imageNotice} from '../garment-image.js';
import {basicName} from '../assumed-basics.js';
import {groupedGarments,garmentGroup,canonicalGarmentGroup} from '../garment-model.js';
import {outfitsForGarment} from '../outfit-relationships.js';
import {dataStatus} from './data-status.js';
import {closetOverview} from '../closet-overview.js';

export const moods=[{id:'all',name:'Browse freely'},{id:'relaxed',name:'Keep it casual'},{id:'minimal',name:'Dress sharp'},{id:'street',name:'Add layers'}];
export function refinedMixFilters(outfits,{season='all',style='all'}={}){
 const filters=outfitFilters(outfits,{season}),selected=outfitStyles.some(s=>s.id===style)?style:'all';
 return {...filters,style:selected,visible:filters.inSeason.filter(o=>selected==='all'||o.styleTags?.includes(selected))};
}
export const shortTitle=o=>outfitTitle(o).split('｜').at(-1).trim();
const url=p=>p?.startsWith('/')?p:'/'+p;
const photo=o=>`<img src="${esc(url(o.visual.src))}" alt="${esc(o.visual.alt||outfitTitle(o))}" width="1024" height="1536" loading="lazy">`;
const imageLabel=o=>[o.visual?.kind==='ai'?'AI preview':o.visual?'Outfit photo':'Item combination',o.outfitKind==='planned'?'Includes unpurchased pieces':'',o.assumedBasics?.length?'Assumed base layer':''].filter(Boolean).join(' · ');
const pieceImage=i=>`<img src="${esc(url(thumbnail(i)))}" alt="${esc(i.name)}" width="400" height="500" loading="lazy">`;
const href=(page,{season='all',style='all'}={})=>{const q=new URLSearchParams();if(season!=='all')q.set('season',season);if(style!=='all')q.set('style',style);return '#'+page+(q.size?'?'+q:'');};
function seasonOptions(page,filters){return `<nav class="moods" aria-label="Season range">${[{id:'all',name:'All seasons'},...filters.seasons].map(s=>`<a href="${href(page,{season:s.id,style:filters.style})}" data-filter-link data-filter-key="season:${s.id}" ${filters.season===s.id?'aria-current="page"':''}>${s.name}</a>`).join('')}</nav>`;}
function styleOptions(filters){return `<nav class="moods" aria-label="Outfit style">${[{id:'all',name:'All styles'},...outfitStyles].map(s=>`<a href="${href('outfits',{season:filters.season,style:s.id})}" data-filter-link data-filter-key="style:${s.id}" ${filters.style===s.id?'aria-current="page"':''}>${s.name}</a>`).join('')}</nav>`;}
function cards(outfits){return outfits.map(o=>`<article class="look" data-outfit-id="${esc(o.id)}"><button class="look-image" data-outfit="${esc(o.id)}" aria-label="View outfit ${esc(o.code||o.id)}">${o.visual?photo(o):'<span class="no-visual">View item combination ↗</span>'}</button><div class="look-copy"><span class="look-code">${esc(o.code||'')}</span><h2><button data-outfit="${esc(o.id)}" title="${esc(outfitTitle(o))}">${esc(shortTitle(o))}</button></h2><span class="visual-label">${esc(imageLabel(o))}</span></div></article>`).join('');}
const empty=()=>'<div class="empty"><p>No outfits in this range. Try another filter.</p></div>';

export function savedOutfitsView({outfits,season='all',style='all'}){
 const filters=refinedMixFilters(outfits,{season,style});
 return `<section class="page-heading"><div><h1>My outfits</h1><p>The outfits you chose, in one place.</p></div><span class="list-count" role="status">${countLabel(filters.visible.length,'outfit')}</span></section><div class="browse-filters"><div class="filter-row"><span class="filter-label">Season</span>${seasonOptions('outfits',filters)}</div><div class="filter-row"><span class="filter-label">Style</span>${styleOptions(filters)}<span class="subtle order-note">In saved order</span></div></div><section class="look-grid" aria-label="Saved outfits">${cards(filters.visible)||empty()}</section>`;
}
export function mixView({filters,batch}){
 const batchLabel=batch.batchNumber<=1?'Random picks':`Batch ${batch.batchNumber}`;
 return `<section class="page-heading"><div><h1>What feels right today?</h1><p>Same wardrobe, different mood.</p></div><span class="list-count" role="status" aria-live="polite" aria-atomic="true">${batchLabel} · ${countLabel(batch.outfits.length,'outfit')} / ${countLabel(batch.total,'outfit')}</span></section><div class="browse-filters"><div class="filter-row"><span class="filter-label">Mood</span><nav class="moods" aria-label="Choose a mood">${moods.map(m=>`<a href="${href('mix',{season:filters.season,style:m.id})}" data-mood="${m.id}" data-filter-link data-filter-key="mood:${m.id}" ${filters.style===m.id?'aria-current="page"':''}>${m.name}</a>`).join('')}</nav></div><div class="filter-row"><span class="filter-label">Season</span>${seasonOptions('mix',filters)}<button class="primary shuffle-next" data-next ${batch.canAdvance?'':'disabled'}>Shuffle again <span aria-hidden="true">↻</span></button></div></div><section class="look-grid" aria-label="Current batch">${cards(batch.outfits)||empty()}</section>${batch.total>0&&!batch.canAdvance?`<p class="small-pool">Only ${countLabel(batch.total,'outfit')} in this range; all are shown. Widen the filters to see more.</p>`:''}`;
}
export function closetView({items,layer='all',group='all',usage='all',usageCounts=null,personalStatus='ready',pending=false,overview=false}){
 const showOverview=overview&&!pending;
 const active=items.filter(pending?isPendingDiscard:isActiveGarment),options=[['all','All'],['outer','Outerwear'],['inner','Tops'],['bottom','Bottoms'],['shoes','Shoes'],['accessory','Accessories']],page=pending?'discard':'closet';
 const selected=options.some(([id])=>id===layer)?layer:'all',candidates=active.filter(i=>selected==='all'||i.layer===selected),groups=groupedGarments(candidates),requested=canonicalGarmentGroup(group),selectedGroup=groups.some(g=>g.id===requested)?requested:'all';
 const inGroup=candidates.filter(i=>selectedGroup==='all'||garmentGroup(i).id===selectedGroup),selectedUsage=!showOverview&&!pending&&['unused','low'].includes(usage)?usage:'all',known=selectedUsage==='all'||usageCounts!==null;
 const visible=inGroup.filter(i=>selectedUsage==='all'||usageCounts&&(selectedUsage==='unused'?(usageCounts.get(i.id)||0)===0:(usageCounts.get(i.id)||0)>=1&&(usageCounts.get(i.id)||0)<=2));
 const pendingCount=items.filter(isPendingDiscard).length;
 const secondary=pending?'<a class="quiet-link" href="#closet">← My wardrobe</a>':`<a class="quiet-link" href="#discard">Ready to let go · ${pendingCount}</a>`;
 const filters=`<details class="scope closet-filter"><summary>Filters <span aria-hidden="true">⌄</span>${selectedGroup!=='all'||selectedUsage!=='all'?'<i class="filter-active" aria-label="Filters active"></i>':''}</summary><div class="scope-content"><label class="select-field"><span>Subtype</span><select data-closet-filter="group" aria-label="Item subtype"><option value="all">All subtypes</option>${groups.map(g=>`<option value="${esc(g.id)}" ${selectedGroup===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>${!pending?`<label class="select-field"><span>Outfit use</span><select data-closet-filter="usage" aria-label="Saved outfit use">${[['all','All items'],['unused','Not in any outfits'],['low','In 1–2 outfits']].map(([id,name])=>`<option value="${id}" ${selectedUsage===id?'selected':''}>${name}</option>`).join('')}</select></label><p>Counts links to saved outfits, not actual wears.</p>`:''}</div></details>`;
 return `<section class="page-heading"><div><h1>${pending?'Ready to let go':showOverview?'Wardrobe overview':'My wardrobe'}</h1><p>${pending?'Set aside for now. Its record and code are kept.':showOverview?'See categories and color families at a glance.':'Your familiar clothes, with new ways to wear them.'}</p></div><div class="closet-heading-tools"><span class="list-count" role="status">${showOverview?countLabel(active.length,'active item'):known?countLabel(visible.length,'item'):'Outfit links unavailable'}</span>${secondary}</div></section><div class="closet-toolbar"><nav class="moods closet-tabs" aria-label="Item categories">${options.map(([id,name])=>`<a href="#${page}${id==='all'?'':'?layer='+id}" data-filter-link data-filter-key="layer:${id}" ${!showOverview&&selected===id?'aria-current="page"':''}>${name}</a>`).join('')}${!pending?`<a href="#closet?view=overview" data-filter-link data-filter-key="view:overview" ${showOverview?'aria-current="page"':''}>Wardrobe overview</a>`:''}</nav>${showOverview?'':filters}</div>${showOverview?closetOverview(items):!known?dataStatus('personal','Outfit links',personalStatus==='loading'?'loading':'error'):`<section class="garment-grid">${visible.map(i=>`<article class="garment" data-garment-id="${esc(i.id)}"><button class="garment-image" data-garment="${esc(i.id)}" aria-label="View item ${esc(displayCode(i))}">${pieceImage(i)}</button><div class="garment-copy"><span>${esc(displayCode(i))}</span><h2><button data-garment="${esc(i.id)}" title="${esc(i.name)}">${esc(i.name)}</button></h2></div>${isReconstructed(i)?`<span class="garment-evidence" title="${esc(imageNotice)}">AI-prepared image</span>`:''}</article>`).join('')||'<p class="empty">No items in this range.</p>'}</section>`}`;
}
const close=dialog=>`<button class="close" data-close="${dialog}" aria-label="Close ${dialog==='outfit-detail'?'outfit':'item'} details">×</button>`;
const ownershipNotes=outfit=>(outfit.outfitKind==='planned'?`<div class="ownership-note"><h3>Not yet complete</h3>${(outfit.suggestedPieces||[]).map(p=>`<p>${esc(p.name)} · Not purchased</p>`).join('')}<p>These pieces are not counted in your wardrobe.</p></div>`:'')+(outfit.assumedBasics?.length?`<div class="ownership-note"><h3>Includes an assumed base layer</h3>${outfit.assumedBasics.map(b=>`<p>${esc(basicName(b))} · ${esc(b.exposure)}</p>`).join('')}<p>Shown as an approved assumption, not counted in your wardrobe.</p></div>`:'');
export function outfitDetailView(outfit,items,{asPage=false,catalogStatus='ready',relationships=null}={}){
 const members=Object.values(outfit.selection||{}).map(id=>items.find(i=>i.id===id)).filter(Boolean);
 const origin=relationships?.origins.find(r=>r.outfitId===outfit.id),derived=origin?.available?`<p class="origin-note">A variation of <a href="#outfits/${encodeURIComponent(origin.sourceId)}">${esc(origin.sourceCode||origin.sourceTitle)}</a></p>`:outfit.derivedFromOutfitId?'<p class="origin-note">The original outfit link is kept in the record.</p>':'';
 return `${asPage?'':close('outfit-detail')}<div class="detail-visual">${outfit.visual?`<button class="detail-zoom" data-outfit-image="${esc(outfit.id)}" aria-label="Enlarge outfit ${esc(outfit.code||outfit.id)}">${photo(outfit)}<span>Enlarge ↗</span></button>`:'<p>No image for this outfit yet.</p>'}</div><section class="detail-copy"><span class="detail-code">${esc(outfit.code)} · ${outfitSeasonName(outfit.season)} · ${outfitStyleNames(outfit).join(' / ')}</span><h2 id="outfit-title">${esc(shortTitle(outfit))}</h2><p class="detail-image-label">${esc(imageLabel(outfit))} · Check details and fit against the real items</p><h3>How to wear it</h3>${outfit.wearingNotes?.length?`<ul>${outfit.wearingNotes.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p>No styling notes for this outfit yet.</p>'}<h3>Items in this outfit</h3>${catalogStatus==='ready'?`<div class="detail-pieces">${members.map(i=>`<button data-garment="${esc(i.id)}" aria-label="View item ${esc(displayCode(i))}">${pieceImage(i)}<span>${esc(displayCode(i))}</span></button>`).join('')}</div>`:dataStatus('catalog','Wardrobe items',catalogStatus)}${derived}${ownershipNotes(outfit)}</section>`;
}
export function garmentDetailView(item,outfits,{relationships=null,personalStatus='ready'}={}){
 const related=personalStatus==='ready'?outfitsForGarment(item.id,outfits,relationships):null;
 return `${close('garment-detail')}<div class="detail-visual garment-detail-image">${pieceImage(item)}</div><section class="detail-copy"><span class="detail-code">${esc(displayCode(item))}</span><h2 id="garment-title">${esc(item.name)}</h2><p>${esc(item.subtype)} · ${esc(item.color?.name)}</p>${isReconstructed(item)?`<p class="image-evidence">AI-prepared image · ${esc(imageNotice)}</p>`:''}${isPendingDiscard(item)?'<p class="image-evidence">Set aside for new outfits. Its record and saved outfit links are kept.</p>':''}${related===null?dataStatus('personal','Outfit links',personalStatus==='loading'?'loading':'error'):`<h3>Appears in ${countLabel(related.length,'saved outfit')}</h3><div class="related-looks">${related.map(o=>`<button data-related-outfit="${esc(o.id)}" aria-label="View outfit ${esc(o.code||o.id)}">${o.visual?photo(o):'<span>Item combination</span>'}<span>${esc(o.code)} · ${esc(shortTitle(o))}${o.outfitKind==='planned'?' · Includes unpurchased pieces':''}</span></button>`).join('')||'<p>No saved outfits for this item yet.</p>'}</div><p class="image-evidence">Counts saved outfit links, not actual wears.</p>`}</section>`;
}
export function outfitZoomView(outfit){return `<button class="close" data-close="outfit-image" aria-label="Close outfit image">×</button><h2 id="outfit-image-title">${esc(outfit.code)} · ${esc(shortTitle(outfit))}</h2>${photo(outfit)}<p>${esc(imageLabel(outfit))} · This is not a photo of you wearing the outfit. Check the real items.</p>${ownershipNotes(outfit)}`;}
export function personalNotesView(saved){return `<section class="page-heading"><div><h1>Outfit notes</h1><p>Keep notes on how you wear your clothes.</p></div><a class="quiet-link" href="#outfits">← My outfits</a></section><div class="personal-notes">${saved.map(n=>`<article><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></article>`).join('')||'<p class="empty">No outfit notes yet.</p>'}</div>`;}
